input.contents:
var fs = require('fs');
var path = require('path');

var srcPath = path.join(__dirname, 'Ban_Lanh_Dao.html');
var html = fs.readFileSync(srcPath, 'utf8');

var styleMatch = html.match(/<style>([\s\S]*?)<\/style>/);
var scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
var mainStart = html.indexOf('<main>');
var mainEnd = html.indexOf('</main>') + 7;
var mainContent = html.substring(mainStart, mainEnd);

if (!styleMatch || !scriptMatch || mainStart < 0) {
  console.error('Could not parse source file');
  process.exit(1);
}

var css = styleMatch[1];
var js = scriptMatch[1];

// Remove header/footer related CSS blocks
css = css.replace(/\/\* Header inherited[\s\S]*?\.nav a:hover, \.nav a\.active \{[^}]+\}\s*\n\s*\n/, '');
css = css.replace(/\/\* Contact and footer \*\/[\s\S]*?\.footer-bottom \{[^}]+\}\s*\n\s*\n/, '');

// Remove header/footer media query rules
css = css.replace(/\s*\.top-bar-left span:first-child \{ display: none; \}\s*\n/, '');
css = css.replace(/\s*\.nav \{ overflow-x: auto; max-width: 68vw; \}\s*\n/, '');
css = css.replace(/\s*\.nav a \{ white-space: nowrap; \}\s*\n/, '');
css = css.replace(/\s*\.footer-top \{ grid-template-columns: repeat\(2, 1fr\); \}\s*\n/, '');
css = css.replace(/\s*\.top-bar \{ display: none; \}\s*\n/, '');
css = css.replace(/\s*\.header \.container \{ min-height: 66px; align-items: center; overflow: hidden; \}\s*\n/, '');
css = css.replace(/\s*\.brand-mark \{ width: 42px; height: 42px; \}\s*\n/, '');
css = css.replace(/\s*\.brand-copy strong \{ font-size: 14px; \}\s*\n/, '');
css = css.replace(/\s*\.nav \{ max-width: 60vw; \}\s*\n/, '');
css = css.replace(/\s*\.nav a \{ padding: 8px 10px; font-size: 13px; \}\s*\n/, '');
css = css.replace(/\s*\.footer-top \{ grid-template-columns: 1fr; gap: 32px; \}\s*\n/, '');

// Keep letterhead styles but rename comment
css = css.replace(/\/\* Contact and footer \*\//, '/* Contact letterhead */');

var indexHtml = [
  '<!DOCTYPE html>',
  '<html lang="vi">',
  '<head>',
  '  <meta charset="UTF-8">',
  '  <meta http-equiv="X-Content-Type-Options" content="nosniff">',
  '  <meta http-equiv="Referrer-Policy" content="strict-origin-when-cross-origin">',
  '  <meta name="referrer" content="strict-origin-when-cross-origin">',
  '  <meta name="robots" content="noindex,nofollow">',
  '  <meta name="viewport" content="width=device-width, initial-scale=1.0">',
  '  <meta name="theme-color" content="#0D7A3E">',
  '  <meta name="description" content="Ban Giám đốc và Hội đồng Quản trị nhiệm kỳ VII 2024–2028 của Bệnh viện Tim Tâm Đức.">',
  '  <title>Ban Lãnh Đạo - Bệnh viện Tim Tâm Đức</title>',
  '  <link rel="preconnect" href="https://fonts.googleapis.com">',
  '  <link href="https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500;600;700&family=Be+Vietnam+Pro:wght@300;400;500;600;700&display=swap" rel="stylesheet">',
  '  <link rel="stylesheet" href="style.css">',
  '</head>',
  '<body>',
  mainContent,
  '  <script src="script.js"></script>',
  '</body>',
  '</html>'
].join('\n');

fs.writeFileSync(path.join(__dirname, 'index.html'), indexHtml, 'utf8');
fs.writeFileSync(path.join(__dirname, 'style.css'), css.trim() + '\n', 'utf8');
fs.writeFileSync(path.join(__dirname, 'script.js'), js.trim() + '\n', 'utf8');

console.log('Created index.html (' + indexHtml.length + ' bytes)');
console.log('Created style.css (' + css.length + ' bytes)');
console.log('Created script.js (' + js.length + ' bytes)');

var fs = require('fs');
var path = require('path');

var dir = __dirname;
var srcPath = path.join(dir, 'Ban_Lanh_Dao.html');
var html = fs.readFileSync(srcPath, 'utf8');

var styleMatch = html.match(/<style>([\s\S]*?)<\/style>/);
var scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
var mainStart = html.indexOf('<main>');
var mainEnd = html.indexOf('</main>') + 7;
var mainContent = html.substring(mainStart, mainEnd);

if (!styleMatch || !scriptMatch || mainStart < 0) {
  console.error('Could not parse source file');
  process.exit(1);
}

var css = styleMatch[1];
var js = scriptMatch[1];

// Remove header CSS block
css = css.replace(/\/\* Header inherited[\s\S]*?\.nav a:hover, \.nav a\.active \{[^}]+\}\s*\n\s*\n/, '');

// Remove only footer CSS, keep letterhead
css = css.replace(/\/\* Contact and footer \*\//, '/* Contact letterhead */');
css = css.replace(/\.footer \{[\s\S]*?\.footer-bottom \{[^}]+\}\s*\n\s*\n/, '');

// Remove header/footer media query rules
css = css.replace(/\s*\.top-bar-left span:first-child \{ display: none; \}\s*\n/g, '');
css = css.replace(/\s*\.nav \{ overflow-x: auto; max-width: 68vw; \}\s*\n/g, '');
css = css.replace(/\s*\.nav a \{ white-space: nowrap; \}\s*\n/g, '');
css = css.replace(/\s*\.footer-top \{ grid-template-columns: repeat\(2, 1fr\); \}\s*\n/g, '');
css = css.replace(/\s*\.top-bar \{ display: none; \}\s*\n/g, '');
css = css.replace(/\s*\.header \.container \{ min-height: 66px; align-items: center; overflow: hidden; \}\s*\n/g, '');
css = css.replace(/\s*\.brand-mark \{ width: 42px; height: 42px; \}\s*\n/g, '');
css = css.replace(/\s*\.brand-copy strong \{ font-size: 14px; \}\s*\n/g, '');
css = css.replace(/\s*\.nav \{ max-width: 60vw; \}\s*\n/g, '');
css = css.replace(/\s*\.nav a \{ padding: 8px 10px; font-size: 13px; \}\s*\n/g, '');
css = css.replace(/\s*\.footer-top \{ grid-template-columns: 1fr; gap: 32px; \}\s*\n/g, '');

// Keep brand mark for letterhead section
var brandMarkCss = [
  '    .brand-mark {',
  '      width: 46px; height: 46px; display: grid; place-items: center; border-radius: 50%;',
  '      background: var(--primary); color: var(--white); font-size: 21px; box-shadow: inset 0 0 0 5px rgba(255,255,255,.18);',
  '    }',
  ''
].join('\n');
css = css.replace(/\.sr-only \{[\s\S]*?\}\s*\n\s*\n/, function (m) { return m + brandMarkCss; });

// Image paths -> img/
css = css.replace(/url\('ban-lanh-dao-break\.webp'\)/g, "url('img/ban-lanh-dao-break.webp')");
mainContent = mainContent.replace(/src="ban-lanh-dao-hero\.webp"/g, 'src="img/ban-lanh-dao-hero.webp"');

var imgDir = path.join(dir, 'img');
if (!fs.existsSync(imgDir)) {
  fs.mkdirSync(imgDir);
}

['ban-lanh-dao-hero.webp', 'ban-lanh-dao-break.webp'].forEach(function (name) {
  var src = path.join(dir, name);
  var dest = path.join(imgDir, name);
  if (fs.existsSync(src)) {
    fs.copyFileSync(src, dest);
  }
});

var indexHtml = [
  '<!DOCTYPE html>',
  '<html lang="vi">',
  '<head>',
  '  <meta charset="UTF-8">',
  '  <meta http-equiv="X-Content-Type-Options" content="nosniff">',
  '  <meta http-equiv="Referrer-Policy" content="strict-origin-when-cross-origin">',
  '  <meta name="referrer" content="strict-origin-when-cross-origin">',
  '  <meta name="robots" content="noindex,nofollow">',
  '  <meta name="viewport" content="width=device-width, initial-scale=1.0">',
  '  <meta name="theme-color" content="#0D7A3E">',
  '  <meta name="description" content="Ban Giám đốc và Hội đồng Quản trị nhiệm kỳ VII 2024–2028 của Bệnh viện Tim Tâm Đức.">',
  '  <title>Ban Lãnh Đạo - Bệnh viện Tim Tâm Đức</title>',
  '  <link rel="preconnect" href="https://fonts.googleapis.com">',
  '  <link href="https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500;600;700&family=Be+Vietnam+Pro:wght@300;400;500;600;700&display=swap" rel="stylesheet">',
  '  <link rel="stylesheet" href="style.css">',
  '</head>',
  '<body>',
  mainContent,
  '  <script src="script.js"></script>',
  '</body>',
  '</html>'
].join('\n');

fs.writeFileSync(path.join(dir, 'index.html'), indexHtml, 'utf8');
fs.writeFileSync(path.join(dir, 'style.css'), css.trim() + '\n', 'utf8');
fs.writeFileSync(path.join(dir, 'script.js'), js.trim() + '\n', 'utf8');

console.log('Done: index.html, style.css, script.js, img/');

